const MOD int64 = 1000000007
const MOD_TOTIENT int64 = MOD - 1

func pow(base int64, power int64) int64 {
	e := power % MOD_TOTIENT
	if e < 0 {
		e += MOD_TOTIENT
	}
	if e == 0 && base == 0 {
		return base
	}
	b := base % MOD
	res := int64(1)
	for e > 0 {
		if e&1 != 0 {
			res = (res * b) % MOD
		}
		b = (b * b) % MOD
		e >>= 1
	}
	return res
}

